def algorithm(func, dim, lb, ub, budget, rng):
    x_best = (ub - lb) * rng.rand(dim)
    f_best = func(x_best)

    for i in range(budget):
        x_cand = x_best + (ub - lb) * (rng.rand(dim) - 0.5) / np.sqrt(i + 1)
        f_cand = func(np.clip(x_cand, a_min=lb, a_max=ub))

        if f_cand < f_best:
            x_best = x_cand
            f_best = f_cand

    return x_best

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.full(dim, 0.5 * (lb + ub))
    best_y = func(best_x)

    for _ in range(budget):
        x = np.clip(np.random.uniform(lb, ub, size=dim), a_min=lb, a_max=ub)
        y = func(x)

        if y < best_y:
            best_y = y
            best_x = x

    return best_x
